1	export interface Customer {
2	  yearsWithMHPCO: number;
3	}
4	
5	/** An item a customer brings to be insured, as the office records it. */
6	export interface Item {
7	  type: string;
8	  material?: string;
9	  cursed?: boolean;
10	  enchantment?: number;
11	}
12	
13	const PROCESSING_FEE = 5;
14	
15	/**
16	 * How the office classes an item on its price list. Main items each have a row of
17	 * their own; components share a single uniform rate, and the office's
18	 * building-block offer is written for components alone.
19	 */
20	type PriceListClass = "main item" | "component";
21	
22	/** One row of the MHPCO price list: what the office charges to insure one such item. */
23	interface PriceListEntry {
24	  class: PriceListClass;
25	  basePremium: number;
26	  insuranceValue: number;
27	}
28	
29	const COMPONENT_BASE_PREMIUM = 25;
30	const COMPONENT_INSURANCE_VALUE = 250;
31	
32	/**
33	 * The MHPCO price list, as posted at the counter: every kind of item the office
34	 * recognises, and what it charges for one of them. An item type absent from the
35	 * list is one the office does not insure.
36	 */
37	const PRICE_LIST: Record<string, PriceListEntry> = {
38	  sword: { class: "main item", basePremium: 100, insuranceValue: 1000 },
39	  amulet: { class: "main item", basePremium: 60, insuranceValue: 600 },
40	  staff: { class: "main item", basePremium: 80, insuranceValue: 800 },
41	  potion: { class: "main item", basePremium: 40, insuranceValue: 400 },
42	  rune: {
43	    class: "component",
44	    basePremium: COMPONENT_BASE_PREMIUM,
45	    insuranceValue: COMPONENT_INSURANCE_VALUE,
46	  },
47	  moonstone: {
48	    class: "component",
49	    basePremium: COMPONENT_BASE_PREMIUM,
50	    insuranceValue: COMPONENT_INSURANCE_VALUE,
51	  },
52	};
53	
54	/** The price list's row for the given item type. */
55	function priceListEntryOf(type: string): PriceListEntry {
56	  return PRICE_LIST[type];
57	}
58	
59	function isComponentType(type: string): boolean {
60	  return priceListEntryOf(type).class === "component";
61	}
62	
63	/** The price-list base premium for one item of the given type. */
64	function catalogueBasePremiumOf(type: string): number {
65	  return priceListEntryOf(type).basePremium;
66	}
67	
68	const BLOCK_SIZE = 3;
69	const BLOCK_BASE_PREMIUM = 60;
70	
71	/** A policy's items of one and the same type -- what the office calls "alike". */
72	interface AlikeItems {
73	  type: string;
74	  items: Item[];
75	}
76	
77	/**
78	 * The office groups a policy's items into groups of alike items, because its
79	 * building-block offer is priced per group rather than per item. "Alike" means
80	 * the same item type.
81	 */
82	function groupAlikeItems(items: Item[]): AlikeItems[] {
83	  const groups = new Map<string, AlikeItems>();
84	  for (const item of items) {
85	    const group = groups.get(item.type);
86	    if (group === undefined) {
87	      groups.set(item.type, { type: item.type, items: [item] });
88	    } else {
89	      group.items.push(item);
90	    }
91	  }
92	  return [...groups.values()];
93	}
94	
95	/**
96	 * A building block of exactly 3 alike components is offered at a special base
97	 * premium instead of the catalogue rate; any other count is priced per component.
98	 */
99	function isBuildingBlock({ type, items }: AlikeItems): boolean {
100	  return isComponentType(type) && items.length === BLOCK_SIZE;
101	}
102	
103	/** Without an offer, the office simply charges the catalogue rate for every item. */
104	function catalogueRateBasePremiumOf({ type, items }: AlikeItems): number {
105	  return items.length * catalogueBasePremiumOf(type);
106	}
107	
108	/** What the office charges for one group of alike items covered by the same policy. */
109	function alikeItemsBasePremiumOf(alikeItems: AlikeItems): number {
110	  return isBuildingBlock(alikeItems)
111	    ? BLOCK_BASE_PREMIUM
112	    : catalogueRateBasePremiumOf(alikeItems);
113	}
114	
115	const HIGH_ENCHANTMENT_LEVEL = 5;
116	
117	function isCursed(item: Item): boolean {
118	  return item.cursed === true;
119	}
120	
121	/** The office considers an item highly enchanted from enchantment level 5 upwards. */
122	function isHighlyEnchanted(item: Item): boolean {
123	  return (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_LEVEL;
124	}
125	
126	/**
127	 * One clause of the office's risk schedule: the risk it looks for in a single
128	 * item, and the surcharge it levies on that item's base premium when it finds it.
129	 */
130	interface ItemRiskClause {
131	  appliesTo: (item: Item) => boolean;
132	  surchargeRate: number;
133	}
134	
135	/** The office's schedule of item-specific risks, as written in its statutes. */
136	const ITEM_RISK_CLAUSES: ItemRiskClause[] = [
137	  { appliesTo: isCursed, surchargeRate: 0.5 },
138	  { appliesTo: isHighlyEnchanted, surchargeRate: 0.3 },
139	];
140	
141	/**
142	 * Item-specific risk surcharges are charged on the base premium of the affected
143	 * item alone, never on the policy total. An item that carries several risks is
144	 * surcharged for each of them, the office adding the rates together.
145	 */
146	function itemRiskSurchargeRateOf(item: Item): number {
147	  return ITEM_RISK_CLAUSES.filter((clause) => clause.appliesTo(item)).reduce(
148	    (rate, clause) => rate + clause.surchargeRate,
149	    0,
150	  );
151	}
152	
153	/**
154	 * How much of a group's base premium each alike item is held to carry. Group
155	 * offers such as the building block are priced per group, so the office has to
156	 * decide what an individual item inside a group is worth before it can charge an
157	 * item-specific surcharge on it. The office's reading: alike items are
158	 * interchangeable, so each carries an equal share of the group's base premium
159	 * (20 G each inside a 60 G block). Shares are kept as exact fractions.
160	 */
161	function apportionedBasePremiumOf(alikeItems: AlikeItems): number {
162	  return alikeItemsBasePremiumOf(alikeItems) / alikeItems.items.length;
163	}
164	
165	/** One item paired with the base premium the office holds it to carry. */
166	interface ItemBasePremium {
167	  item: Item;
168	  basePremium: number;
169	}
170	
171	/** What each item of a group contributes to the policy base premium. */
172	function itemBasePremiumsOf(alikeItems: AlikeItems): ItemBasePremium[] {
173	  const basePremium = apportionedBasePremiumOf(alikeItems);
174	  return alikeItems.items.map((item) => ({ item, basePremium }));
175	}
176	
177	/** What an item's own risks add to its base premium, in G. */
178	function itemRiskSurchargeOf({ item, basePremium }: ItemBasePremium): number {
179	  return basePremium * itemRiskSurchargeRateOf(item);
180	}
181	
182	/**
183	 * How the office rates the items of one policy. The two quantities are kept
184	 * apart because the office rates its policy-wide terms against one of them and
185	 * not the other: the policy base premium is their rating basis, while item risk
186	 * surcharges ride on top of it untouched by any policy-wide term.
187	 */
188	interface ItemRating {
189	  policyBasePremium: number;
190	  itemRiskSurcharges: number;
191	}
192	
193	/**
194	 * The item side of the premium: it depends on the items alone and knows nothing
195	 * of who brings them.
196	 */
197	function itemRatingOf(items: Item[]): ItemRating {
198	  const itemBasePremiums = groupAlikeItems(items).flatMap(itemBasePremiumsOf);
199	  return {
200	    policyBasePremium: itemBasePremiums.reduce((total, { basePremium }) => total + basePremium, 0),
201	    itemRiskSurcharges: itemBasePremiums.reduce(
202	      (total, itemBasePremium) => total + itemRiskSurchargeOf(itemBasePremium),
203	      0,
204	    ),
205	  };
206	}
207	
208	const LOYALTY_DISCOUNT_RATE = -0.2;
209	const LOYALTY_YEARS = 2;
210	
211	/** The office calls a customer long-standing after 2 years of business. */
212	function isLongStandingCustomer(customer: Customer): boolean {
213	  return customer.yearsWithMHPCO >= LOYALTY_YEARS;
214	}
215	
216	/**
217	 * Everything the office knows when it rates the policy-wide terms of one
218	 * contract: the customer it is writing for, and its own history of contracts
219	 * already written for them. Terms are earned by either, so a clause of the
220	 * office's schedule is rated against the pair rather than against one of them.
221	 */
222	interface PolicyCircumstances {
223	  customer: Customer;
224	  contractsAlreadyWritten: number;
225	}
226	
227	/**
228	 * The office grants its follow-up discount on each contract it writes for a
229	 * customer after their first, so the term is earned by the contracts already
230	 * written rather than by the customer's record.
231	 */
232	function isFollowUpContract({ contractsAlreadyWritten }: PolicyCircumstances): boolean {
233	  return contractsAlreadyWritten > 0;
234	}
235	
236	/**
237	 * One clause of the office's schedule of policy-wide terms: the circumstances it
238	 * looks for in the contract before it, and the rate it then applies to the policy
239	 * base premium. Surcharges carry a positive rate, discounts a negative one -- the
240	 * office's own arithmetic, which adds its policy-wide rates together.
241	 */
242	interface PolicyModifierClause {
243	  appliesTo: (circumstances: PolicyCircumstances) => boolean;
244	  modifierRate: number;
245	}
246	
247	/**
248	 * Each quoted item is a first insurance whatever the customer's history, so the
249	 * office's initial assessment is earned by no record and withheld from none --
250	 * the one scheduled term whose circumstances are always met.
251	 */
252	const FIRST_INSURANCE_SURCHARGE_RATE = 0.1;
253	
254	const FOLLOW_UP_CONTRACT_DISCOUNT_RATE = -0.15;
255	
256	/**
257	 * The office's schedule of policy-wide terms: the initial assessment it levies on
258	 * every contract it writes, what a long-standing record entitles the customer to,
259	 * and what the standing of this contract in their history grants them.
260	 */
261	const POLICY_MODIFIER_CLAUSES: PolicyModifierClause[] = [
262	  { appliesTo: () => true, modifierRate: FIRST_INSURANCE_SURCHARGE_RATE },
263	  {
264	    appliesTo: ({ customer }) => isLongStandingCustomer(customer),
265	    modifierRate: LOYALTY_DISCOUNT_RATE,
266	  },
267	  { appliesTo: isFollowUpContract, modifierRate: FOLLOW_UP_CONTRACT_DISCOUNT_RATE },
268	];
269	
270	/**
271	 * Every policy-wide term the office rates on the policy base premium -- the sum of
272	 * all item base premiums -- never on a single item: whichever scheduled terms the
273	 * circumstances of this contract earn, the office adding their rates together.
274	 */
275	function policyModifierRateOf(circumstances: PolicyCircumstances): number {
276	  return POLICY_MODIFIER_CLAUSES.filter((clause) => clause.appliesTo(circumstances)).reduce(
277	    (rate, clause) => rate + clause.modifierRate,
278	    0,
279	  );
280	}
281	
282	/**
283	 * What the items and the contract's circumstances come to before the office writes
284	 * the figure down: what the items themselves are worth, adjusted by the policy-wide
285	 * terms the circumstances earn, with the processing fee added at the very end. Kept
286	 * as an exact fraction -- the office rounds the premium and nothing on the way to it.
287	 */
288	function exactPolicyPremiumOf(itemRating: ItemRating, circumstances: PolicyCircumstances): number {
289	  const { policyBasePremium, itemRiskSurcharges } = itemRating;
290	  const modifierRate = policyModifierRateOf(circumstances);
291	  return (
292	    policyBasePremium + itemRiskSurcharges + policyBasePremium * modifierRate + PROCESSING_FEE
293	  );
294	}
295	
296	/**
297	 * A premium is money owed to the office, so rounding it to whole G in the office's
298	 * own favour means rounding up. (The office's other rounded amount, a payout, is
299	 * money it hands out, and its favour points the other way there.)
300	 */
301	function premiumRoundedInMHPCOsFavour(exactPremium: number): number {
302	  return Math.ceil(exactPremium);
303	}
304	
305	/**
306	 * The premium the office charges for covering those items under this contract: what
307	 * the terms come to, rounded to whole G in the office's favour. The office quotes
308	 * whole G, so rounding is part of the premium it decides on and not a later dressing
309	 * up of the figure.
310	 */
311	function policyPremiumOf(itemRating: ItemRating, circumstances: PolicyCircumstances): number {
312	  return premiumRoundedInMHPCOsFavour(exactPolicyPremiumOf(itemRating, circumstances));
313	}
314	
315	const CAP_MULTIPLE_OF_INSURANCE_SUM = 2;
316	
317	/**
318	 * The insurance sum of a policy: what the price list says the covered items are
319	 * insured for. Premium offers and surcharges do not touch it.
320	 */
321	function insuranceSumOf(items: Item[]): number {
322	  return items.reduce((sum, item) => sum + priceListEntryOf(item.type).insuranceValue, 0);
323	}
324	
325	/**
326	 * A policy the office has written: the items it covers and what the office will
327	 * pay out on it in total, capped at twice the insurance sum.
328	 */
329	class Policy {
330	  remainingCap: number;
331	
332	  constructor(readonly items: Item[]) {
333	    this.remainingCap = CAP_MULTIPLE_OF_INSURANCE_SUM * insuranceSumOf(items);
334	  }
335	}
336	
337	/** What a damage report costs the office, and what is left of the policy's cap. */
338	export interface Settlement {
339	  payout: number;
340	  remainingCap: number;
341	}
342	
343	/** One item damaged in an incident, as the customer reports it. */
344	export interface Damage {
345	  itemType: string;
346	  amount: number;
347	}
348	
349	/** A damage report against one policy. */
350	export interface Incident {
351	  cause: string;
352	  damages: Damage[];
353	}
354	
355	/**
356	 * The office as a going concern: it serves one customer for the length of a
357	 * scenario, remembers the contracts it has already written for them -- its
358	 * follow-up discount depends on that history -- and the policies it issued, so
359	 * that later claims can be settled against them.
360	 */
361	export class ClaimOffice {
362	  private readonly policies: Policy[] = [];
363	
364	  constructor(private readonly customer: Customer) {}
365	
366	  quote(items: Item[]): number {
367	    const premium = policyPremiumOf(itemRatingOf(items), {
368	      customer: this.customer,
369	      contractsAlreadyWritten: this.policies.length,
370	    });
371	    this.policies.push(new Policy(items));
372	    return premium;
373	  }
374	
375	  claim(policyIndex: number, _incident: Incident): Settlement {
376	    const policy = this.policies[policyIndex];
377	    return { payout: 0, remainingCap: policy.remainingCap };
378	  }
379	}
380	
381	/** A customer's first and only contract with the office. */
382	export function quote(customer: Customer, items: Item[]): number {
383	  return new ClaimOffice(customer).quote(items);
384	}
