const CAP_MULTIPLE_OF_INSURANCE_SUM = 2;

/**
 * The insurance sum of a policy: what the price list says the covered items are
 * insured for. Premium offers and surcharges do not touch it.
 */
function insuranceSumOf(items: Item[]): number {
  return items.reduce((sum, item) => sum + priceListEntryOf(item.type).insuranceValue, 0);
}

/**
 * The most the office will ever pay out on one policy, all claims together: twice
 * what the covered items are insured for. A statute of the office, rated on the
 * insurance sum and on nothing else -- no premium term and no claim raises or
 * lowers it.
 */
function payoutCapOf(items: Item[]): number {
  return CAP_MULTIPLE_OF_INSURANCE_SUM * insuranceSumOf(items);
}

/**
 * A policy the office has written: the items it covers, and how much of its payout
 * cap is still available. The cap is the policy's own ledger -- it starts at the
 * office's capped amount and only the policy itself may draw it down -- so the
 * office reads what remains rather than keeping that figure for it.
 */
class Policy {
  private cap: number;

  constructor(readonly items: Item[]) {
    this.cap = payoutCapOf(items);
  }

  get remainingCap(): number {
    return this.cap;
  }
}

/** What a damage report costs the office, and what is left of the policy's cap. */
export interface Settlement {
  payout: number;
  remainingCap: number;
}

/** One item damaged in an incident, as the customer reports it. */
export interface Damage {
  itemType: string;
  amount: number;
}

/** A damage report against one policy. */
export interface Incident {
  cause: string;
  damages: Damage[];
}

/**
 * The office as a going concern: it serves one customer for the length of a
 * scenario, remembers the contracts it has already written for them -- its
 * follow-up discount depends on that history -- and the policies it issued, so
 * that later claims can be settled against them.
 */
export class ClaimOffice {
  private readonly policies: Policy[] = [];

  constructor(private readonly customer: Customer) {}

  quote(items: Item[]): number {
    const premium = policyPremiumOf(itemRatingOf(items), {
      customer: this.customer,
      contractsAlreadyWritten: this.policies.length,
    });
    this.policies.push(new Policy(items));
    return premium;
  }

  /**
   * Settling a damage report against one of the office's policies. The office
   * does not yet read the report: no clause of its claim schedule -- deductible,
   * high enchantment, dragon material -- has been written down here, so every
   * report settles at nothing and leaves the policy's cap untouched.
   */
  claim(policyIndex: number, incident: Incident): Settlement {
    const policy = this.policies[policyIndex];
    return { payout: 0, remainingCap: policy.remainingCap };
  }
